mapper.select:
SELECT c.id, c.name, c.slug, c.description, c.post_count, c.parent_id, p.name AS parent_name, c.sort_order FROM categories c LEFT JOIN categories p ON c.parent_id = p.id WHERE c.is_visible = true
AND c.parent_id = #{params.parentId}
AND c.post_count >= #{params.minPostCount} ORDER BY c.post_count DESC, c.sort_order, c.id LIMIT #{params.limit}
